# Seed content source for Grade 6. Run build_curriculum.py to regenerate curriculum.json.
# Q(difficulty, prompt, options, answer, hint, explanation) — options=[] means typed answer.

def Q(d, prompt, options, answer, hint, explanation):
    return {"difficulty": d, "prompt": prompt, "options": options, "answer": answer, "hint": hint, "explanation": explanation}

def EX(title, content, visual=""):
    return {"title": title, "content": content, "visual": visual}

