     Q("MEDIUM", "What is the plural of 'baby'?", [], "babies", "Consonant + y → change y to i and add -es.", "baby → babies."),
     Q("HARD", "Find the collective noun: 'The army marched through the town.'", ["army", "marched", "town", "the"], "army", "Which word names a group of people?", "An army is a group of soldiers."),
